<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='history';$pageTitle='Approved History';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$rows=[];$r=$conn->query("SELECT ss.id,ss.schedule_reference,ss.period_start,ss.period_end,ss.participant_count,ss.total_amount,ss.version_number,ss.supersedes_schedule_id,ss.approved_at,m.first_name maker_first_name,m.last_name maker_last_name,a.first_name approver_first_name,a.last_name approver_last_name FROM stipend_schedules ss JOIN users m ON m.id=ss.created_by LEFT JOIN users a ON a.id=ss.approved_by WHERE ss.status='approved' ORDER BY ss.approved_at DESC LIMIT 300");if($r)while($x=$r->fetch_assoc())$rows[]=$x;require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Immutable Audit History</span><h2>Approved History</h2><p>Approved schedules remain unchanged; corrections are represented by revisions.</p></div></div><div class="fo-alert fo-alert--info"><i class="fas fa-lock"></i><div><strong>Approved history is read-only.</strong><span>Historical records cannot be silently edited from this portal.</span></div></div><div class="fo-card"><div class="fo-table-wrap"><table><thead><tr><th>Reference</th><th>Period</th><th>Participants</th><th>Total</th><th>Version</th><th>Maker</th><th>Approver</th><th>Approved</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><strong><?= e($x['schedule_reference']) ?></strong></td><td><?= e(fo_date($x['period_start'])) ?> - <?= e(fo_date($x['period_end'])) ?></td><td><?= number_format((int)$x['participant_count']) ?></td><td><?= e(fo_money($x['total_amount'])) ?></td><td><?= number_format((int)$x['version_number']) ?><?php if($x['supersedes_schedule_id']):?><span>Revision of #<?= (int)$x['supersedes_schedule_id'] ?></span><?php endif;?></td><td><?= e(trim($x['maker_first_name'].' '.$x['maker_last_name'])) ?></td><td><?= e(trim(($x['approver_first_name']??'').' '.($x['approver_last_name']??''))) ?></td><td><?= e(fo_datetime($x['approved_at'])) ?></td><td><a class="fo-icon-btn" href="<?= url('finance_officer/schedule_view.php?id='.(int)$x['id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/_layout_end.php';?>